function removeDuplicados(valores: string[]): string[] {
  const result: string[] = [];
  const seen = new Set<string>();
  for (const value of valores) {
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}

console.assert(removeDuplicados(['ana', 'bia', 'ana', 'caio', 'bia']).toString() === ['ana', 'bia', 'caio'].toString(), 'Test 1 failed');
console.assert(removeDuplicados([]).toString() === '[]', 'Test 2 failed');
console.assert(removeDuplicados(['x']).toString() === ['x'].toString(), 'Test 3 failed');

